"""Generated byte fixtures, no native data/model files."""

import hashlib

import pytest

from scripts import fresh_presentation_byte_guard_v1 as guard


def record(path, content):
    return dict(path=str(path), bytes=len(content), sha256=hashlib.sha256(content).hexdigest())


def fixture(tmp_path):
    root = tmp_path / "root"
    root.mkdir()
    local = root / "inside.bin"
    outside = tmp_path / "outside.bin"
    local.write_bytes(b"synthetic local")
    outside.write_bytes(b"synthetic outside")
    return (
        root,
        local,
        outside,
        [record(local, b"synthetic local"), record(outside, b"synthetic outside")],
    )


def test_whole_preflight_refuses_before_any_open(tmp_path, monkeypatch):
    root, _, _, records = fixture(tmp_path)
    monkeypatch.setattr(
        guard, "stream", lambda path: pytest.fail("must not read before whole authorization")
    )
    with pytest.raises(guard.ByteGuardError, match="unapproved"):
        guard.preflight(records, root, {})


def test_exact_outside_policy_and_two_fresh_phases(tmp_path):
    root, _, outside, records = fixture(tmp_path)
    allow = {guard.key(outside.resolve()): (records[1]["bytes"], records[1]["sha256"])}
    snapshot = guard.preflight(records, root, allow)
    assert guard.phase(snapshot) == 2
    assert guard.phase(snapshot) == 2


def test_hash_policy_mismatch_refuses_before_read(tmp_path, monkeypatch):
    root, _, outside, records = fixture(tmp_path)
    monkeypatch.setattr(guard, "stream", lambda path: pytest.fail("unauthorized read"))
    allow = {guard.key(outside.resolve()): (records[1]["bytes"], "0" * 64)}
    with pytest.raises(guard.ByteGuardError, match="unapproved"):
        guard.preflight(records, root, allow)


def test_same_size_mutation_rejected(tmp_path):
    root, local, _, records = fixture(tmp_path)
    snapshot = guard.preflight(records[:1], root, {})
    guard.phase(snapshot)
    local.write_bytes(b"SYNTHETIC LOCAL")
    with pytest.raises(guard.ByteGuardError, match="bytes changed"):
        guard.phase(snapshot)


def test_conflicting_alias_claims_rejected(tmp_path):
    root, local, _, records = fixture(tmp_path)
    with pytest.raises(guard.ByteGuardError, match="conflicting"):
        guard.preflight([records[0], record(local, b"other")], root, {})


@pytest.mark.parametrize("key,value", [("bytes", True), ("sha256", "ABC"), ("path", False)])
def test_invalid_record_types(tmp_path, key, value):
    root, _, _, records = fixture(tmp_path)
    records[0][key] = value
    with pytest.raises(guard.ByteGuardError, match="invalid byte record"):
        guard.preflight(records[:1], root, {})


def test_retarget_alias_refused_without_open(tmp_path, monkeypatch):
    root, local, _, records = fixture(tmp_path)
    snapshot = guard.preflight(records[:1], root, {})
    other = root / "other.bin"
    other.write_bytes(b"synthetic local")
    monkeypatch.setattr(guard, "resolve", lambda spelling, base: other.resolve())
    monkeypatch.setattr(
        guard, "stream", lambda path: pytest.fail("retarget must be refused before read")
    )
    with pytest.raises(guard.ByteGuardError, match="retargeted"):
        guard.phase(snapshot)


@pytest.mark.parametrize(
    "claim",
    [(False, "0" * 64), (-1, "0" * 64), (0, "A" * 64), [0, "0" * 64], (0,)],
)
def test_invalid_policy_even_if_unused_refuses_before_read(tmp_path, monkeypatch, claim):
    root, _, outside, records = fixture(tmp_path)
    monkeypatch.setattr(guard, "stream", lambda path: pytest.fail("invalid policy read"))
    with pytest.raises(guard.ByteGuardError, match="invalid outside policy"):
        guard.preflight(records[:1], root, {guard.key(outside.resolve()): claim})


@pytest.mark.parametrize("spelling", ["relative.bin", "", 1])
def test_invalid_policy_path(tmp_path, spelling):
    root, _, _, records = fixture(tmp_path)
    with pytest.raises(guard.ByteGuardError, match="invalid outside policy"):
        guard.preflight(records[:1], root, {spelling: (0, "0" * 64)})


def test_file_cannot_be_root(tmp_path):
    _, local, _, records = fixture(tmp_path)
    with pytest.raises(guard.ByteGuardError, match="root directory"):
        guard.preflight(records[:1], local, {})


def test_zero_byte_policy_bool_does_not_authorize(tmp_path):
    root, _, outside, records = fixture(tmp_path)
    outside.write_bytes(b"")
    records[1] = record(outside, b"")
    with pytest.raises(guard.ByteGuardError, match="invalid outside policy"):
        guard.preflight(records, root, {guard.key(outside.resolve()): (False, records[1]["sha256"])})
